fn days_to_next_sunday(day: &str) -> i8 {
    // Map each day to an index 0 (Sunday) to 6 (Saturday)
    let day_index = match day {
        "SUN" => 0,
        "MON" => 1,
        "TUE" => 2,
        "WED" => 3,
        "THU" => 4,
        "FRI" => 5,
        "SAT" => 6,
        _ => unreachable!("Input is guaranteed valid"), // Defensive but not necessary per problem statement
    };

    let days_until = (7 - day_index) % 7;
    if days_until == 0 {
        7
    } else {
        days_until as i8
    }
}